CREATE TRIGGER memory_ai AFTER INSERT ON memory BEGIN
            INSERT INTO memory_fts(rowid, topic, content)
            VALUES (new.id, new.topic, new.content);
        END;
CREATE INDEX idx_state_cells_case_status
            ON state_cells(case_id, status, priority, conflict_group);
CREATE INDEX idx_context_items_prompt
            ON context_items(case_id, semantic_key, contamination_class,
                trust_class, source_fingerprint);
CREATE INDEX idx_runtime_decisions_unfinished
            ON runtime_decisions(case_id, status, selected_at);
CREATE INDEX idx_state_edges_scope_status
            ON state_edges(scope, status, relation);
CREATE INDEX idx_state_edges_refs
            ON state_edges(from_ref_kind, from_ref_id, to_ref_kind, to_ref_id);
